import re
from datetime import date, datetime, time, timedelta

_MONTHS = ["JAN", "FEB", "MAR", "APR", "MAY", "JUN",
           "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"]
_DAYS = ["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"]

# (low, high, names) for minute, hour, day of month, month, day of week.
_FIELDS = [
    (0, 59, {}),
    (0, 23, {}),
    (1, 31, {}),
    (1, 12, {name: i for i, name in enumerate(_MONTHS, 1)}),
    (0, 7, {name: i for i, name in enumerate(_DAYS)}),
]

_ITEM = re.compile(r"(\*|(\w+)(?:-(\w+))?)(?:/([0-9]+))?", re.ASCII)


def _value(text: str, low: int, high: int, names: dict[str, int]) -> int:
    if text.isdigit():
        value = int(text)
    elif text.upper() in names:
        value = names[text.upper()]
    else:
        raise ValueError(f"invalid value {text!r}")
    if not low <= value <= high:
        raise ValueError(f"value {value} outside {low}-{high}")
    return value


def _field(text: str, low: int, high: int, names: dict[str, int]) -> set[int]:
    values: set[int] = set()
    for item in text.split(","):
        match = _ITEM.fullmatch(item)
        if not match:
            raise ValueError(f"invalid item {item!r}")
        whole, first, last, step = match.groups()
        if whole == "*":
            start, stop = low, high
        else:
            start = _value(first, low, high, names)
            if last is not None:
                stop = _value(last, low, high, names)
                if start > stop:
                    raise ValueError(f"invalid range {item!r}")
            elif step is not None:
                stop = high
            else:
                stop = start
        increment = 1 if step is None else int(step)
        if increment < 1:
            raise ValueError(f"invalid step in {item!r}")
        values.update(range(start, stop + 1, increment))
    return values


def _five_years_after(moment: datetime) -> datetime:
    if moment.year + 5 > datetime.max.year:
        return datetime.max
    day = 28 if (moment.month, moment.day) == (2, 29) else moment.day
    return moment.replace(year=moment.year + 5, day=day)


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError(f"expected 5 fields, got {len(fields)}")
    minutes, hours, days, months, weekdays = (
        _field(text, *spec) for text, spec in zip(fields, _FIELDS))
    minutes, hours = sorted(minutes), sorted(hours)
    weekdays = {day % 7 for day in weekdays}
    either = fields[2] != "*" and fields[4] != "*"

    def day_matches(day: date) -> bool:
        in_month = day.day in days
        in_week = day.isoweekday() % 7 in weekdays
        return (in_month or in_week) if either else (in_month and in_week)

    def first_time(day: date, earliest: time) -> datetime | None:
        for hour in hours:
            if hour >= earliest.hour:
                low = earliest.minute if hour == earliest.hour else 0
                for minute in minutes:
                    if minute >= low:
                        return datetime.combine(day, time(hour, minute))
        return None

    failure = ValueError(f"no match for {expression!r} within five years")
    limit = _five_years_after(after)
    try:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        raise failure from None
    day = start.date()
    while day <= limit.date():
        if day.month not in months:
            # Skip the rest of the month.
            if day.year == date.max.year and day.month == 12:
                break
            if day.month == 12:
                day = date(day.year + 1, 1, 1)
            else:
                day = date(day.year, day.month + 1, 1)
            continue
        if day_matches(day):
            earliest = start.time() if day == start.date() else time()
            found = first_time(day, earliest)
            if found is not None:
                if found > limit:
                    break
                return found
        if day == date.max:
            break
        day += timedelta(days=1)
    raise failure

